<section class="garden-panel" id="project-site"><div class="garden-panel-heading"><div><span class="garden-kicker">HORTICULTURIST FIELD BOOK</span><h2>Site inspections & field records</h2></div></div>
<?php if (!$garden_workbench_ready): ?><p>Run the pending project workbench migration (4.0.9.159) to enable structured records and task cards.</p><?php elseif ($editable): ?>
<details class="garden-record-compose" id="garden-site-assessment" <?= $project->stage==='enquiry' || !$inspection ? 'open' : ''; ?>><summary class="garden-create-summary"><span><i class="fa fa-plus" aria-hidden="true"></i> Record a site inspection</span><small>Checks, measurements & recommendations</small></summary>
<form method="post" action="<?= base_url('garden/project_record'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="record_type" value="inspection"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>">
<div class="garden-inspection-grid"><?php foreach (mp_garden_inspection_fields() as $key=>$definition): $type=$definition[1];$value=$inspection['fields'][$key] ?? ($key==='visit_date' ? date('Y-m-d') : ''); ?>
<?php if (($definition[2] ?? '')==='checks'): ?><fieldset class="garden-inspection-checks"><legend><?= htmlspecialchars($definition[0]); ?></legend><div><?php foreach ($type as $option=>$label): ?><label><input type="checkbox" name="fields[<?= $key; ?>][]" value="<?= $option; ?>" <?= is_array($value) && in_array($option,$value,true) ? 'checked' : ''; ?>> <?= htmlspecialchars($label); ?></label><?php endforeach; ?></div></fieldset>
<?php elseif (is_array($type)): ?><label><?= htmlspecialchars($definition[0]); ?><select name="fields[<?= $key; ?>]" data-garden-select hidden><option value="">Choose</option><?php foreach ($type as $option=>$label): ?><option value="<?= $option; ?>" <?= $value===$option ? 'selected' : ''; ?>><?= htmlspecialchars($label); ?></option><?php endforeach; ?></select></label>
<?php elseif ($type==='text'): ?><div class="garden-inspection-text"><label><?= htmlspecialchars($definition[0]); ?><textarea id="inspection-<?= $key; ?>" name="fields[<?= $key; ?>]" rows="3" maxlength="6000" <?= $key==='recommendations' ? 'required' : ''; ?>><?= htmlspecialchars($value); ?></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'inspection-'.$key]); ?></div>
<?php else: ?><label><?= htmlspecialchars($definition[0]); ?><input type="<?= in_array($type,['number','ph'],true) ? 'number' : 'date'; ?>" name="fields[<?= $key; ?>]" value="<?= htmlspecialchars($value); ?>" <?= in_array($type,['number','ph'],true) ? 'min="0" step="0.01" max="'.($type==='ph' ? 14 : 100000).'"' : ''; ?> <?= $key==='visit_date' ? 'required' : ''; ?>></label><?php endif; ?>
<?php endforeach; ?></div><label>Additional observations<textarea id="inspection-other-notes" name="note" maxlength="8000" rows="3"></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'inspection-other-notes']); ?><?php if ($project->stage==='enquiry'): ?><input type="hidden" name="complete_inspection" value="1"><?php endif; ?><div class="garden-save-row"><button class="garden-button"><?= $project->stage==='enquiry' ? 'Save assessment & complete inspection' : 'Save inspection record'; ?></button><span>Creates a dated record. Earlier records remain in the field book.</span></div></form></details>
<?php if ($project->stage!=='enquiry'): ?><details class="garden-record-compose"><summary class="garden-create-summary"><span><i class="fa fa-pencil" aria-hidden="true"></i> Add a progress or completion note</span></summary><form method="post" action="<?= base_url('garden/project_record'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= $jobId; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><label>Record type<select name="record_type" data-garden-select hidden><option value="progress">Progress / field observation</option><option value="completion">Completion / handover</option></select></label><label>Field note<textarea id="garden-field-note" name="note" rows="4" maxlength="8000" required></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'garden-field-note']); ?><button class="garden-button">Save field note</button></form></details><?php endif; ?>
<p class="garden-voice-explainer">Dictation uses your browser’s speech service, which may process audio online. Start it only when ready, then review the text before saving. You can always type.</p>
<?php endif; ?>
<div class="garden-field-records"><?php foreach ($garden_records as $record): $fields=json_decode($record->fields_json ?? '',true) ?: []; ?><article class="garden-field-record"><div><span class="garden-pill"><?= htmlspecialchars(ucfirst($record->record_type)); ?></span><small><?= htmlspecialchars($record->created_at.' · '.($record->author ?: 'Team member')); ?></small></div>
<?php if ($fields): ?><details><summary class="garden-disclosure-toggle">View site assessment</summary><dl class="garden-field-values"><?php foreach (mp_garden_inspection_fields() as $key=>$definition): $value=$fields[$key] ?? '';if ($value==='' || $value===[]) continue;if (is_array($value)) $value=implode(', ',array_map(function($v) use($definition){return $definition[1][$v] ?? $v;},$value));elseif (is_array($definition[1])) $value=$definition[1][$value] ?? $value; ?><div><dt><?= htmlspecialchars($definition[0]); ?></dt><dd><?= nl2br(htmlspecialchars($value)); ?></dd></div><?php endforeach; ?></dl></details><?php endif; ?>
<?php if ($record->note): ?><p><?= nl2br(htmlspecialchars($record->note)); ?></p><?php endif; ?></article><?php endforeach; ?>
<?php if (!$garden_records): ?><div class="garden-empty"><i class="fa fa-clipboard" aria-hidden="true"></i><h3>No field records yet</h3><p>Capture what you observed, what was agreed and the next steps for the site.</p></div><?php endif; ?></div></section>
